CREATE SCHEMA auth;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE anon NOLOGIN;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.actor',true),'')::uuid$$;
CREATE FUNCTION public.current_tenant_escola_id() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.school',true),'')::uuid$$;
CREATE TABLE public.role_fixture (school uuid, actor uuid, role text, PRIMARY KEY(school,actor,role));
CREATE FUNCTION public.user_has_role_in_school(p_school uuid,p_roles text[]) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT EXISTS(SELECT 1 FROM public.role_fixture WHERE school=p_school AND actor=auth.uid() AND role=ANY(p_roles))$$;
CREATE FUNCTION public.canonicalize_matricula_status_text(p_status text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT CASE WHEN p_status IN ('ativo','ativa','matriculado') THEN 'ativo' ELSE p_status END$$;
CREATE TABLE public.turmas (id uuid PRIMARY KEY,escola_id uuid NOT NULL,ano_letivo int,classe_id uuid,curso_id uuid,session_id uuid,capacidade_maxima int);
CREATE TABLE public.matriculas (id uuid PRIMARY KEY,escola_id uuid NOT NULL,turma_id uuid REFERENCES public.turmas(id),status text,session_id uuid,updated_at timestamptz,updated_by uuid);
CREATE TABLE public.audit_logs (id bigserial PRIMARY KEY,escola_id uuid,actor_id uuid,action text,entity text,entity_id text,portal text,details jsonb,before jsonb,after jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE public.notas (id uuid PRIMARY KEY,matricula_id uuid REFERENCES public.matriculas(id),valor int);
CREATE TABLE public.pagamentos (id uuid PRIMARY KEY,matricula_id uuid REFERENCES public.matriculas(id),valor int);
CREATE TABLE public.presencas (id uuid PRIMARY KEY,matricula_id uuid REFERENCES public.matriculas(id),presente boolean);
